from collections import Counter
from functools import lru_cache


class Solution:
    def canDistribute(self, nums: List[int], quantity: List[int]) -> bool:
        counts = list(Counter(nums).values())
        quantity.sort(reverse=True)
        m = len(quantity)
        full = (1 << m) - 1
        need = [0] * (1 << m)
        for mask in range(1, 1 << m):
            low = mask & -mask
            need[mask] = need[mask ^ low] + quantity[low.bit_length() - 1]

        @lru_cache(maxsize=None)
        def dfs(i, served):
            if served == full:
                return True
            if i == len(counts):
                return False
            free = full ^ served
            sub = free
            while True:
                if need[sub] <= counts[i] and dfs(i + 1, served | sub):
                    return True
                if sub == 0:
                    break
                sub = (sub - 1) & free
            return False

        return dfs(0, 0)

