class Solution {
    private Map<Integer, Boolean> memo;
    private int[] need, counts, quantity;
    private int m, full;

    public boolean canDistribute(int[] nums, int[] quantity) {
        Map<Integer, Integer> freq = new HashMap<>();
        for (int v : nums) freq.merge(v, 1, Integer::sum);
        counts = new int[freq.size()];
        int idx = 0;
        for (int c : freq.values()) counts[idx++] = c;
        this.quantity = quantity.clone();
        Arrays.sort(this.quantity);
        m = quantity.length;
        full = (1 << m) - 1;
        need = new int[full + 1];
        for (int mask = 1; mask <= full; mask++) {
            int low = mask & -mask;
            int bit = Integer.numberOfTrailingZeros(low);
            need[mask] = need[mask ^ low] + this.quantity[m - 1 - bit];
        }
        memo = new HashMap<>();
        return dfs(0, 0);
    }

    private boolean dfs(int i, int served) {
        if (served == full) return true;
        if (i == counts.length) return false;
        Boolean cached = memo.get(i * (full + 1) + served);
        if (cached != null) return cached;
        boolean res = false;
        int free = full ^ served;
        for (int sub = free;; sub = (sub - 1) & free) {
            if (need[sub] <= counts[i] && dfs(i + 1, served | sub)) {
                res = true;
                break;
            }
            if (sub == 0) break;
        }
        memo.put(i * (full + 1) + served, res);
        return res;
    }
}

