class Solution {
public:
    bool canDistribute(vector<int>& nums, vector<int>& quantity) {
        unordered_map<int, int> freq;
        for (int v : nums) freq[v]++;
        vector<int> counts;
        for (auto& [_, c] : freq) counts.push_back(c);
        int m = quantity.size(), full = (1 << m) - 1;
        vector<int> need(full + 1, 0);
        for (int mask = 1; mask <= full; mask++) {
            int low = mask & (-mask);
            need[mask] = need[mask ^ low] + quantity[__builtin_ctz(low)];
        }
        vector<char> dp(full + 1, 0), nxt(full + 1, 0);
        dp[0] = 1;
        for (int c : counts) {
            nxt = dp;
            for (int served = 0; served <= full; served++) {
                if (!dp[served]) continue;
                int free = full ^ served;
                for (int sub = free; sub; sub = (sub - 1) & free)
                    if (need[sub] <= c) nxt[served | sub] = 1;
            }
            if (nxt[full]) return true;
            swap(dp, nxt);
        }
        return dp[full];
    }
};

