class Solution {
    public boolean canDistribute(int[] nums, int[] quantity) {
        Map<Integer, Integer> freq = new HashMap<>();
        for (int v : nums) freq.merge(v, 1, Integer::sum);
        List<Integer> counts = new ArrayList<>(freq.values());
        int m = quantity.length, full = (1 << m) - 1;
        int[] need = new int[full + 1];
        for (int mask = 1; mask <= full; mask++) {
            int low = mask & -mask;
            need[mask] = need[mask ^ low] + quantity[Integer.numberOfTrailingZeros(low)];
        }
        boolean[] dp = new boolean[full + 1], nxt = new boolean[full + 1];
        dp[0] = true;
        for (int c : counts) {
            System.arraycopy(dp, 0, nxt, 0, full + 1);
            for (int served = 0; served <= full; served++) {
                if (!dp[served]) continue;
                int free = full ^ served;
                for (int sub = free; sub > 0; sub = (sub - 1) & free)
                    if (need[sub] <= c) nxt[served | sub] = true;
            }
            if (nxt[full]) return true;
            boolean[] tmp = dp; dp = nxt; nxt = tmp;
        }
        return dp[full];
    }
}

